(async () => {
    const m = window.__mymechanics; const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
    await m.actions.ensureKernel();
    if (m.state.editing) m.actions.cancelEditing({ quiet: true });
    await m.actions.closeProject({ force: true });
    await m.actions.openSampleAsk('asmRobot'); await sleep(1200);
    const a = m.active();
    const g = a.components.find((c) => c.sub);
    if (!g) return 'no sub-assembly';
    const sub = m.project.assemblies.find((x) => x.id === g.sub);
    const keys = [...m.viewport.bodies.keys()].filter((k) => k.startsWith('comp:' + g.id + '/'));
    const pos = (k) => { const e = m.viewport.bodies.get(k).mesh.matrix.elements; return [e[12], e[13], e[14]]; };
    const before = new Map(keys.map((k) => [k, pos(k)]));
    m.state.selection = [{ kind: 'comp', id: g.id }];
    const enabled = m.commands.flexibleComponent.enabled();
    await m.run('flexibleComponent'); await sleep(600);
    const poses = Object.keys(g.flexPose ?? {}).length;
    const failed = m.state.failedMates.size;
    let moved = 0; for (const k of keys) { const p = pos(k); const b = before.get(k); if (Math.hypot(p[0] - b[0], p[1] - b[1], p[2] - b[2]) > 1e-3) moved++; }
    const checked = m.commands.flexibleComponent.checked();
    await m.run('undo'); await sleep(300);
    const undone = !m.active().components.find((c) => c.id === g.id).flexible;
    await m.run('redo'); await sleep(300);
    const redone = Boolean(m.active().components.find((c) => c.id === g.id).flexible);
    m.state.selection = [{ kind: 'comp', id: g.id }];
    await m.run('flexibleComponent'); await sleep(300);
    const g2 = m.active().components.find((c) => c.id === g.id);
    return [enabled, poses === sub.components.length, failed, moved, checked, undone, redone, Boolean(g2.flexible), g2.flexPose === undefined].join(' ');
  })()
